import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
        except StopIteration:
            break

        edges = []
        for _ in range(n - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            edges.append((u, v))

        if n == 1:
            results.append("1")
            continue

        adj = [[] for _ in range(n + 1)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        visited = [False] * (n + 1)
        queue = [1]
        visited[1] = True
        order = []

        head = 0
        while head < len(queue):
            u = queue[head]
            head += 1
            order.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)

        result_perm = [0] * n
        for idx, node in enumerate(order):
            result_perm[idx] = idx + 1

        results.append(" ".join(map(str, result_perm)))

    sys.stdout.write("\n".join(results) + "\n")

if __name__ == "__main__":
    solve()
